"""Generate RTL constants from the golden model, so the two cannot drift apart.

  python model/gen_rtl.py      # writes src/filterbank_coeffs.vh
"""

from pathlib import Path

import frontend

ROOT = Path(__file__).resolve().parent.parent


def filterbank_coeffs_vh():
    g, a1, a2 = frontend.filterbank_coeffs()
    lines = [
        "// Generated by model/gen_rtl.py from frontend.filterbank_coeffs(). Do not edit.",
        f"// Q2.{frontend.COEF_FRAC} band-pass biquad coefficients, centers "
        + ", ".join(f"{f:.0f}" for f in frontend.band_centers()) + " Hz.",
        "// term 0: g, term 1: -a1, term 2: -a2 (negated so every term is added).",
        "function automatic signed [15:0] fb_coef(input [3:0] band, input [1:0] term);",
        "  case ({band, term})",
    ]
    for b in range(frontend.N_BANDS):
        for t, c in enumerate((g[b], -a1[b], -a2[b])):
            c = int(c)
            lit = f"16'sd{c}" if c >= 0 else f"-16'sd{-c}"
            lines.append(f"    {{4'd{b}, 2'd{t}}}: fb_coef = {lit};")
    lines += ["    default: fb_coef = 16'sd0;", "  endcase", "endfunction", ""]
    return "\n".join(lines)


if __name__ == "__main__":
    (ROOT / "src" / "filterbank_coeffs.vh").write_text(filterbank_coeffs_vh())
    print("wrote src/filterbank_coeffs.vh")
